cd:=p->>'codigo';
IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc a ON nn.codigo=a.padre) SELECT 1 FROM anc WHERE codigo=p->>'alcance') THEN RAISE EXCEPTION 'S20_SCOPE_P36 %',cd; END IF;
ans:=lf_ops.nucleo_regla_proponer_v1(p,true);
ver:=(ans->>'version')::int;
ver_esp := CASE WHEN cd='S19-C05' THEN 2 ELSE 1 END;
IF ans->>'resultado'<>'CANDIDATA' OR ver IS DISTINCT FROM ver_esp THEN RAISE EXCEPTION 'S20_PROPOSAL_FAIL % %',cd,ans; END IF;
ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=ver AND estado='CANDIDATA') OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=ver)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_aplicaciones WHERE regla=cd AND nodo=p->>'alcance' AND modo='HEREDA') THEN RAISE EXCEPTION 'S20_READBACK_FAIL %',cd; END IF;
n:=n+1;
END LOOP;
IF n<>5 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA')<>b_cand+4 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='PUBLICADA')<>b_pub OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla='S19-C05' AND version=1 AND estado='DESCARTADA' AND hash='64dcdff5a740529e060f0b526b4f810cd05c6cee19beea35927800856bad8846') OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S20_INVARIANT_FAIL'; END IF;
IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S20_DPIG03_FAIL'; END IF;
RAISE NOTICE 'S20_PASS 5 CANDIDATAS 40 VECTORES DPIG03=0';
END $s20$;
COMMIT;
